import { expect, test, type Page } from "@playwright/test";
import { waitForAnimationsToEnd } from "../fixtures/animations";
import { waitHydrated } from "../fixtures/esplora";

// #505 (F4c): sheets, confirmation dialogs, «Collega» row, date and time
// fields of the gallery section «Fogli, conferme e data», in the light and in
// the dark theme, on mobile and desktop. The references are generated by the
// visual tester (`visual-baseline`); the PR lists them.

test.use({
  locale: "it-IT",
  timezoneId: "Europe/Rome",
  reducedMotion: "reduce",
});

const NOW = new Date("2026-11-18T09:00:00Z");

const tid = (page: Page, id: string) => page.getByTestId(id);

const OPEN_STATES: {
  name: string;
  wrapper: string;
  opener: string;
  after?: (page: Page) => Promise<void>;
}[] = [
  {
    name: "foglio-azione",
    wrapper: "ds-foglio-azione",
    opener: "Apri Nuovo impegno",
  },
  {
    name: "foglio-piede",
    wrapper: "ds-foglio-piede",
    opener: "Apri Nuova scadenza",
  },
  {
    name: "foglio-lungo",
    wrapper: "ds-foglio-lungo",
    opener: "Apri Nuova scadenza lunga",
  },
  {
    name: "foglio-titolo-inizio",
    wrapper: "ds-foglio-titolo-inizio",
    opener: "Apri titolo lungo",
  },
  { name: "conferma", wrapper: "ds-conferma", opener: "Togli Biscotto" },
  {
    name: "conferma-errore",
    wrapper: "ds-conferma-errore",
    opener: "Togli Biscotto",
    after: async (page) => {
      await page.getByRole("button", { name: "Togli dal Nest" }).click();
      await expect(
        page.getByRole("alertdialog").getByRole("alert"),
      ).toBeVisible();
    },
  },
];

for (const scheme of ["light", "dark"] as const) {
  test.describe(`fogli, conferme e data, tema ${scheme}`, () => {
    test.beforeEach(async ({ page }) => {
      await page.emulateMedia({ colorScheme: scheme });
      await page.clock.install({ time: NOW });
      await page.goto("/design-system");
      await page.evaluate(() => document.fonts.ready);
      await waitHydrated(tid(page, "ds-data"));
    });

    for (const state of OPEN_STATES) {
      test(`#505: ${state.name} aperto`, async ({ page }) => {
        await tid(page, state.wrapper)
          .getByRole("button", { name: state.opener })
          .click();
        await state.after?.(page);
        await waitForAnimationsToEnd(page);
        await page.mouse.move(0, 0);
        await expect(page).toHaveScreenshot(`${state.name}-${scheme}.png`);
      });
    }

    test("#505: calendario del mese aperto", async ({ page }) => {
      await tid(page, "ds-data")
        .getByRole("button", { name: /^Giorno/ })
        .click();
      await expect(page.getByRole("grid")).toBeVisible();
      await waitForAnimationsToEnd(page);
      await page.mouse.move(0, 0);
      await expect(page).toHaveScreenshot(`calendario-${scheme}.png`);
    });

    test("#505: calendario con «Togli la data»", async ({ page }) => {
      await tid(page, "ds-data-facoltativa")
        .getByRole("button", { name: /^Data di nascita/ })
        .click();
      await expect(page.getByTestId("calendario-togli")).toBeVisible();
      await waitForAnimationsToEnd(page);
      await page.mouse.move(0, 0);
      await expect(page).toHaveScreenshot(`calendario-togli-${scheme}.png`);
    });

    for (const id of [
      "ds-collega",
      "ds-data",
      "ds-data-anno",
      "ds-data-limiti",
      "ds-data-vuota",
      "ds-ora",
    ]) {
      test(`#505: esempio ${id}`, async ({ page }) => {
        const example = tid(page, id).locator("xpath=ancestor::figure[1]");
        await example.scrollIntoViewIfNeeded();
        await page.mouse.move(0, 0);
        await expect(example).toHaveScreenshot(`${id}-${scheme}.png`);
      });
    }

    test("#505: «Collega» collegato e in errore", async ({ page }) => {
      const rows = tid(page, "ds-collega");
      await rows
        .getByRole("button", { name: "Collega Google Calendar" })
        .click();
      await expect(rows.getByRole("alert")).toBeVisible();
      await rows.getByRole("button", { name: "Collega Outlook" }).click();
      await expect(rows.getByTestId("collega-stato")).toBeVisible();
      await page.mouse.move(0, 0);
      await expect(rows).toHaveScreenshot(`ds-collega-stati-${scheme}.png`);
    });
  });
}
